// ===== MONETIZATION ANALYZER =====
// Analyzes audience and recommends monetization strategy

const input = $input.first().json;
const staticData = $getWorkflowStaticData('global');
const kb = staticData.knowledgeBase || {};
const posts = staticData.posts || [];
const chatId = input.chatId || staticData.chatId;
const niche = staticData.niche || 'your niche';

// Calculate audience readiness
const totalViews = posts.reduce((sum, p) => sum + (p.views || 0), 0);
const totalFollowers = staticData.followerCount || 0;
const avgEngagement = posts.length > 0 ? 
  posts.reduce((sum, p) => sum + ((p.likes || 0) + (p.comments || 0) + (p.saves || 0)), 0) / posts.length : 0;

// Determine monetization readiness level
let readinessLevel = 'NOT_READY';
let readinessScore = 0;

if (totalViews > 100000) { readinessScore += 30; }
if (totalViews > 500000) { readinessScore += 20; }
if (totalFollowers > 1000) { readinessScore += 15; }
if (totalFollowers > 5000) { readinessScore += 15; }
if (avgEngagement > 100) { readinessScore += 10; }
if (avgEngagement > 500) { readinessScore += 10; }

if (readinessScore >= 80) readinessLevel = 'READY_NOW';
else if (readinessScore >= 50) readinessLevel = 'ALMOST_READY';
else readinessLevel = 'BUILDING';

// Monetization strategies based on niche
const monetizationStrategies = {
  // Digital Products
  digitalProducts: [
    {
      type: 'E-Book / Guide',
      description: `Create a comprehensive guide about ${niche}`,
      price: '$9-29',
      effort: 'Medium',
      potential: 'High',
      example: `"The Ultimate ${niche} Blueprint"`
    },
    {
      type: 'Online Course',
      description: `Video course teaching ${niche} mastery`,
      price: '$47-197',
      effort: 'High',
      potential: 'Very High',
      example: `"${niche} Mastery - 6 Week Program"`
    },
    {
      type: 'Templates / Presets',
      description: `Ready-to-use templates for ${niche}`,
      price: '$7-37',
      effort: 'Low',
      potential: 'Medium',
      example: `"${niche} Template Pack"`
    },
    {
      type: 'Cheat Sheet / Checklist',
      description: `Quick reference guide for ${niche}`,
      price: '$5-15',
      effort: 'Low',
      potential: 'Medium',
      example: `"${niche} Quick Start Checklist"`
    }
  ],

  // Services
  services: [
    {
      type: 'Coaching / Consulting',
      description: `1-on-1 ${niche} coaching`,
      price: '$50-500/session',
      effort: 'High',
      potential: 'Very High',
      example: `"${niche} Strategy Session"`
    },
    {
      type: 'Done-For-You Service',
      description: `Handle ${niche} for clients`,
      price: '$500-5000',
      effort: 'Very High',
      potential: 'Very High',
      example: `"We handle your ${niche} so you don't have to"`
    }
  ],

  // Affiliate
  affiliate: [
    {
      type: 'Tool Recommendations',
      description: `Recommend tools you use for ${niche}`,
      price: '10-50% commission',
      effort: 'Low',
      potential: 'Medium',
      example: `"The tools I use daily for ${niche}"`
    },
    {
      type: 'Course Affiliates',
      description: `Promote other creators' courses`,
      price: '20-50% commission',
      effort: 'Low',
      potential: 'Medium',
      example: `"Best ${niche} courses I've taken"`
    }
  ],

  // Community
  community: [
    {
      type: 'Paid Community / Membership',
      description: `Exclusive ${niche} community`,
      price: '$9-49/month',
      effort: 'Medium',
      potential: 'High (recurring!)',
      example: `"${niche} Inner Circle"`
    },
    {
      type: 'Newsletter',
      description: `Premium ${niche} newsletter`,
      price: '$5-15/month',
      effort: 'Medium',
      potential: 'Medium (recurring!)',
      example: `"Weekly ${niche} Insights"`
    }
  ],

  // Sponsorships
  sponsorships: [
    {
      type: 'Brand Deals',
      description: `Partner with ${niche} brands`,
      price: '$100-10000/post',
      effort: 'Low',
      potential: 'High',
      example: `Sponsored carousel or reel`
    },
    {
      type: 'Product Reviews',
      description: `Review ${niche} products`,
      price: '$50-500/review',
      effort: 'Low',
      potential: 'Medium',
      example: `"Honest review of [product]"`
    }
  ]
};

// Audience insights for product fit
const audienceInsights = {
  painPoints: kb.painPoints || [],
  desires: kb.desires || [],
  questions: kb.questions || [],
  language: kb.audienceLanguage || [],
  personas: kb.audiencePersonas || []
};

// Recommend best strategy
let recommendedStrategy = 'digitalProducts';
let reasoning = '';

if (readinessLevel === 'READY_NOW') {
  if (audienceInsights.painPoints.length > 5) {
    recommendedStrategy = 'digitalProducts';
    reasoning = 'Your audience has clear pain points — create a product that solves them!';
  } else if (totalFollowers > 5000) {
    recommendedStrategy = 'community';
    reasoning = 'You have enough followers to build a paid community!';
  } else {
    recommendedStrategy = 'affiliate';
    reasoning = 'Start with affiliate marketing while building your own products!';
  }
}

return [{
  json: {
    chatId,
    niche,
    readinessLevel,
    readinessScore,
    totalViews,
    totalFollowers,
    avgEngagement: Math.round(avgEngagement),
    monetizationStrategies,
    recommendedStrategy,
    reasoning,
    audienceInsights
  }
}];

